SELECT CASE WHEN p.brand IN ('Initech', 'Umbrella') THEN 'group_a' ELSE 'other' END AS brand_group, CASE WHEN p.stock_qty >= 419 THEN 'high' WHEN p.stock_qty >= 153 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, AVG(ss.revenue) AS avg_revenue, MAX(ss.revenue) - MIN(ss.revenue) AS revenue_range FROM store_sales ss LEFT OUTER JOIN products p ON ss.product_id = p.id INNER JOIN suppliers s ON p.supplier_id = s.id WHERE ss.revenue IS NOT NULL GROUP BY CASE WHEN p.brand IN ('Initech', 'Umbrella') THEN 'group_a' ELSE 'other' END, CASE WHEN p.stock_qty >= 419 THEN 'high' WHEN p.stock_qty >= 153 THEN 'mid' ELSE 'low' END HAVING avg_revenue >= 3400 ORDER BY stock_qty_bucket;
